        "下載失敗": [.en: "Download failed", .ja: "ダウンロード失敗", .ko: "다운로드 실패", .zhCN: "下载失败", .es: "Error de descarga", .de: "Download fehlgeschlagen", .fr: "Échec du téléchargement", .ptBR: "Falha no download"],
        "結束後自動產出高精度逐字稿": [
            .en: "Auto high-accuracy transcript after stop",
            .ja: "停止後に高精度文字起こしを自動生成",
            .ko: "정지 후 고정밀 전사 자동 생성",
            .zhCN: "结束后自动产出高精度逐字稿", .es: "Transcripción de alta precisión automática al detener", .de: "Automatisch hochpräzises Transkript nach dem Stopp", .fr: "Transcription haute précision automatique après l’arrêt", .ptBR: "Transcrição de alta precisão automática após parar"],
        "錄音停止後用 Whisper 高精度重轉一次;即時稿僅供會中參考。": [
            .en: "Re-transcribes with Whisper after the recording stops; the live transcript is a meeting-time reference.",
            .ja: "録音停止後に Whisper で高精度に再文字起こしします。ライブ字幕は会議中の参考用です。",
            .ko: "녹음 정지 후 Whisper로 고정밀 재전사합니다. 실시간 자막은 참고용입니다.",
            .zhCN: "录音停止后用 Whisper 高精度重转一次;实时稿仅供会中参考。", .es: "Vuelve a transcribir con Whisper cuando se detiene la grabación; la transcripción en vivo es una referencia durante la reunión.", .de: "Transkribiert nach dem Stopp der Aufnahme noch einmal mit Whisper; das Live-Transkript dient als Orientierung während des Meetings.", .fr: "Retranscrit avec Whisper après l’arrêt de l’enregistrement ; la transcription en direct sert de repère pendant la réunion.", .ptBR: "Transcreve de novo com o Whisper depois que a gravação para; a transcrição ao vivo é uma referência durante a reunião."],
        // UPD 自動更新檢查(zh-lint-skip:.ja/.zhCN 欄為刻意的日文/簡體譯文,比照既有翻譯表慣例)
        "軟體更新": [.en: "Software Update", .ja: "ソフトウェアアップデート", .ko: "소프트웨어 업데이트", .zhCN: "软件更新", .es: "Actualización de software", .de: "Softwareaktualisierung", .fr: "Mise à jour logicielle", .ptBR: "Atualização de software"],
        "關於": [.en: "About", .ja: "このアプリについて", .ko: "정보", .zhCN: "关于", .es: "Acerca de", .de: "Über", .fr: "À propos", .ptBR: "Sobre"],   // MAS-14/16:商店版的版本區段標題
        // MAS-06／07:商店版錄音夾選擇與書籤三態提示(GitHub 版不會出現,但字串兩版共用)
        "選擇錄音資料夾": [.en: "Choose a Recordings Folder", .ja: "録音フォルダを選択", .ko: "녹음 폴더 선택", .zhCN: "选择录音文件夹", .es: "Elige una carpeta de grabaciones", .de: "Ordner für Aufnahmen wählen", .fr: "Choisir un dossier d’enregistrements", .ptBR: "Escolha uma pasta de gravações"],
        "MyParrot 會把錄音與逐字稿存在你選的資料夾;之後可在設定更改。": [.en: "MyParrot saves recordings and transcripts in the folder you choose. You can change it later in Settings.", .ja: "MyParrot は録音と文字起こしを選んだフォルダに保存します。あとで設定から変更できます。", .ko: "MyParrot은 선택한 폴더에 녹음과 전사본을 저장합니다. 나중에 설정에서 변경할 수 있습니다.", .zhCN: "MyParrot 会把录音与文字稿存在你选的文件夹;之后可在设置更改。", .es: "MyParrot guarda las grabaciones y transcripciones en la carpeta que elijas. Puedes cambiarla después en Ajustes.", .de: "MyParrot sichert Aufnahmen und Transkripte im Ordner deiner Wahl. Du kannst ihn später in den Einstellungen ändern.", .fr: "MyParrot enregistre les enregistrements et transcriptions dans le dossier de votre choix. Vous pourrez le changer plus tard dans Réglages.", .ptBR: "O MyParrot salva gravações e transcrições na pasta que você escolher. Você pode mudar depois em Ajustes."],
        "找不到原本的錄音資料夾(可能被搬走或刪除),請重新選擇。": [.en: "The recordings folder can't be found (it may have been moved or deleted). Please choose it again.", .ja: "録音フォルダが見つかりません(移動または削除された可能性があります)。もう一度選択してください。", .ko: "녹음 폴더를 찾을 수 없습니다(이동 또는 삭제되었을 수 있음). 다시 선택해 주세요.", .zhCN: "找不到原本的录音文件夹(可能被移动或删除),请重新选择。", .es: "No se encuentra la carpeta de grabaciones (puede haberse movido o eliminado). Elígela de nuevo.", .de: "Der Aufnahmeordner wurde nicht gefunden (vielleicht verschoben oder gelöscht). Bitte erneut auswählen.", .fr: "Le dossier d’enregistrements est introuvable (peut-être déplacé ou supprimé). Veuillez le choisir à nouveau.", .ptBR: "A pasta de gravações não foi encontrada (pode ter sido movida ou apagada). Escolha-a de novo."],
        "沒有權限寫入原本的錄音資料夾,請重新選擇。": [.en: "MyParrot no longer has permission to write to the recordings folder. Please choose it again.", .ja: "録音フォルダへの書き込み権限がありません。もう一度選択してください。", .ko: "녹음 폴더에 쓸 권한이 없습니다. 다시 선택해 주세요.", .zhCN: "没有权限写入原本的录音文件夹,请重新选择。", .es: "MyParrot ya no tiene permiso para escribir en la carpeta de grabaciones. Elígela de nuevo.", .de: "MyParrot darf nicht mehr in den Aufnahmeordner schreiben. Bitte erneut auswählen.", .fr: "MyParrot n’a plus l’autorisation d’écrire dans le dossier d’enregistrements. Veuillez le choisir à nouveau.", .ptBR: "O MyParrot não tem mais permissão para gravar na pasta de gravações. Escolha-a de novo."],
        "請先選擇錄音資料夾": [.en: "Choose a recordings folder first", .ja: "先に録音フォルダを選択してください", .ko: "먼저 녹음 폴더를 선택하세요", .zhCN: "请先选择录音文件夹", .es: "Elige primero una carpeta de grabaciones", .de: "Bitte zuerst einen Aufnahmeordner wählen", .fr: "Choisissez d’abord un dossier d’enregistrements", .ptBR: "Escolha uma pasta de gravações primeiro"],
        // MAS-16 關於／法務列;MAS-17 一次性錄音提示(兩版都有)
        "隱私政策": [.en: "Privacy Policy", .ja: "プライバシーポリシー", .ko: "개인정보 처리방침", .zhCN: "隐私政策", .es: "Política de privacidad", .de: "Datenschutzerklärung", .fr: "Politique de confidentialité", .ptBR: "Política de privacidade"],
        "原始碼與授權（GitHub，MIT）": [.en: "Source Code & License (GitHub, MIT)", .ja: "ソースコードとライセンス（GitHub、MIT）", .ko: "소스 코드 및 라이선스 (GitHub, MIT)", .zhCN: "源代码与许可（GitHub，MIT）", .es: "Código fuente y licencia (GitHub, MIT)", .de: "Quellcode & Lizenz (GitHub, MIT)", .fr: "Code source et licence (GitHub, MIT)", .ptBR: "Código-fonte e licença (GitHub, MIT)"],
        "第三方授權": [.en: "Third-Party Licenses", .ja: "サードパーティライセンス", .ko: "서드파티 라이선스", .zhCN: "第三方许可", .es: "Licencias de terceros", .de: "Lizenzen von Drittanbietern", .fr: "Licences tierces", .ptBR: "Licenças de terceiros"],
        "錄音前請先告知對方": [.en: "Let the other party know before recording", .ja: "録音前に相手に知らせてください", .ko: "녹음 전에 상대방에게 알려 주세요", .zhCN: "录音前请先告知对方", .es: "Avisa a la otra parte antes de grabar", .de: "Informiere dein Gegenüber vor der Aufnahme", .fr: "Prévenez votre interlocuteur avant d’enregistrer", .ptBR: "Avise a outra pessoa antes de gravar"],
        "依所在地法律，錄音可能需要取得對方同意。這個提醒只會出現一次。": [.en: "Depending on local law, recording may require the other party's consent. This notice is shown only once.", .ja: "お住まいの地域の法律により、録音には相手の同意が必要な場合があります。この通知は一度だけ表示されます。", .ko: "현지 법률에 따라 녹음에는 상대방의 동의가 필요할 수 있습니다. 이 알림은 한 번만 표시됩니다.", .zhCN: "依所在地法律，录音可能需要取得对方同意。这个提醒只会出现一次。", .es: "Según la legislación local, grabar puede requerir el consentimiento de la otra parte. Este aviso solo se muestra una vez.", .de: "Je nach örtlichem Recht kann eine Aufnahme die Zustimmung des Gegenübers erfordern. Dieser Hinweis wird nur einmal angezeigt.", .fr: "Selon la législation locale, l’enregistrement peut nécessiter le consentement de l’autre partie. Cet avertissement ne s’affiche qu’une fois.", .ptBR: "Dependendo da legislação local, gravar pode exigir o consentimento da outra parte. Este aviso aparece só uma vez."],
        "我知道了，開始錄音": [.en: "Got it, start recording", .ja: "了解して録音を開始", .ko: "확인하고 녹음 시작", .zhCN: "我知道了，开始录音", .es: "Entendido, empezar a grabar", .de: "Verstanden, Aufnahme starten", .fr: "Compris, lancer l’enregistrement", .ptBR: "Entendi, começar a gravar"],
        "模型校驗失敗(SHA-256 不符),已捨棄": [.en: "Model checksum mismatch (SHA-256); the download was discarded", .ja: "モデルのチェックサム(SHA-256)が一致しないため、ダウンロードを破棄しました", .ko: "모델 체크섬(SHA-256)이 일치하지 않아 다운로드를 폐기했습니다", .zhCN: "模型校验失败(SHA-256 不符),已丢弃", .es: "La suma de comprobación del modelo no coincide (SHA-256); la descarga se ha descartado", .de: "Prüfsumme des Modells stimmt nicht (SHA-256); der Download wurde verworfen", .fr: "Somme de contrôle du modèle incorrecte (SHA-256) ; le téléchargement a été rejeté", .ptBR: "A soma de verificação do modelo não confere (SHA-256); o download foi descartado"],   // MAS-12
        "啟動時自動檢查更新": [.en: "Check for updates at launch", .ja: "起動時にアップデートを確認", .ko: "실행 시 업데이트 확인", .zhCN: "启动时自动检查更新", .es: "Buscar actualizaciones al iniciar", .de: "Beim Start nach Updates suchen", .fr: "Rechercher les mises à jour au lancement", .ptBR: "Verificar atualizações ao abrir"],
        "立即檢查": [.en: "Check Now", .ja: "今すぐ確認", .ko: "지금 확인", .zhCN: "立即检查", .es: "Buscar ahora", .de: "Jetzt suchen", .fr: "Rechercher maintenant", .ptBR: "Verificar agora"],
        "檢查中…": [.en: "Checking…", .ja: "確認中…", .ko: "확인 중…", .zhCN: "检查中…", .es: "Comprobando…", .de: "Wird geprüft…", .fr: "Vérification…", .ptBR: "Verificando…"],
        "已是最新版本": [.en: "Up to date", .ja: "最新バージョンです", .ko: "최신 버전입니다", .zhCN: "已是最新版本", .es: "Actualizado", .de: "Auf dem neuesten Stand", .fr: "À jour", .ptBR: "Atualizado"],
        "檢查失敗": [.en: "Check failed", .ja: "確認に失敗しました", .ko: "확인 실패", .zhCN: "检查失败", .es: "Error al comprobar", .de: "Prüfung fehlgeschlagen", .fr: "Échec de la vérification", .ptBR: "Falha na verificação"],
        "有新版本": [.en: "New version available:", .ja: "新しいバージョン:", .ko: "새 버전:", .zhCN: "有新版本", .es: "Nueva versión disponible:", .de: "Neue Version verfügbar:", .fr: "Nouvelle version disponible :", .ptBR: "Nova versão disponível:"],
        "前往下載": [.en: "Download", .ja: "ダウンロード", .ko: "다운로드", .zhCN: "前往下载", .es: "Descargar", .de: "Laden", .fr: "Télécharger", .ptBR: "Baixar"],
        "略過此版": [.en: "Skip This Version", .ja: "このバージョンをスキップ", .ko: "이 버전 건너뛰기", .zhCN: "跳过此版本", .es: "Omitir esta versión", .de: "Diese Version überspringen", .fr: "Ignorer cette version", .ptBR: "Ignorar esta versão"],
        "目前版本": [.en: "Current version", .ja: "現在のバージョン", .ko: "현재 버전", .zhCN: "当前版本", .es: "Versión actual", .de: "Aktuelle Version", .fr: "Version actuelle", .ptBR: "Versão atual"],
        "檢查更新…": [.en: "Check for Updates…", .ja: "アップデートを確認…", .ko: "업데이트 확인…", .zhCN: "检查更新…", .es: "Buscar actualizaciones…", .de: "Nach Updates suchen…", .fr: "Rechercher les mises à jour…", .ptBR: "Verificar atualizações…"],
