        // QUIT-12/13(#1697):轉稿中退出的確認框與「上次未完成」標記
        // (zh-lint-skip:.ja/.zhCN 欄為刻意的日文/簡體譯文,比照既有翻譯表慣例)
        "逐字稿還在轉檔中": [
            .en: "A transcript is still being generated",
            .ja: "文字起こしがまだ実行中です",
            .ko: "받아쓰기가 아직 진행 중입니다",
            .zhCN: "字幕还在转写中", .es: "Aún se está generando una transcripción", .de: "Ein Transkript wird noch erstellt", .fr: "Une transcription est encore en cours", .ptBR: "Uma transcrição ainda está sendo gerada"],
        "現在離開會中斷這次轉稿(沒有續傳,下次要整段重轉)。錄音檔會留著。": [
            .en: "Quitting now cancels it — there's no resume, so it starts over next time. Your recording is kept.",
            .ja: "今終了するとこの文字起こしは中断されます(再開はできず、次回は最初からやり直しです)。録音ファイルは残ります。",
            .ko: "지금 종료하면 이 받아쓰기가 중단됩니다(이어하기가 없어 다음에는 처음부터 다시 합니다). 녹음 파일은 남습니다.",
            .zhCN: "现在离开会中断这次转写(没有续传,下次要整段重转)。录音文件会留着。", .es: "Si sales ahora se cancela; no se puede reanudar, así que empezará de cero la próxima vez. La grabación se conserva.", .de: "Beim Beenden wird es abgebrochen. Es gibt kein Fortsetzen, beim nächsten Mal beginnt es von vorn. Deine Aufnahme bleibt erhalten.", .fr: "Quitter maintenant l’annule ; sans reprise possible, elle repartira de zéro la prochaine fois. Votre enregistrement est conservé.", .ptBR: "Sair agora cancela a transcrição; não há como retomar, então ela recomeça do zero na próxima vez. Sua gravação é mantida."],
        "繼續轉稿": [.en: "Keep Transcribing", .ja: "文字起こしを続ける", .ko: "계속 받아쓰기", .zhCN: "继续转写", .es: "Seguir transcribiendo", .de: "Weiter transkribieren", .fr: "Continuer la transcription", .ptBR: "Continuar transcrevendo"],
        "中斷並離開": [.en: "Cancel & Quit", .ja: "中断して終了", .ko: "중단하고 종료", .zhCN: "中断并离开", .es: "Cancelar y salir", .de: "Abbrechen & beenden", .fr: "Annuler et quitter", .ptBR: "Cancelar e sair"],
        "上次未完成": [.en: "Unfinished last time", .ja: "前回は未完了", .ko: "지난번 미완료", .zhCN: "上次未完成", .es: "Sin terminar la última vez", .de: "Beim letzten Mal nicht abgeschlossen", .fr: "Inachevé la dernière fois", .ptBR: "Não concluída da última vez"],
        // #2417 逐字稿校正層(zh-lint-skip:.ja/.zhCN 欄為刻意的日文/簡體譯文,比照既有翻譯表慣例)
        "逐字稿校正": [.en: "Transcript correction", .ja: "文字起こしの校正", .ko: "받아쓰기 교정", .zhCN: "逐字稿校正", .es: "Corrección de transcripción", .de: "Transkriptkorrektur", .fr: "Correction de transcription", .ptBR: "Correção de transcrição"],
        "關閉": [.en: "Off", .ja: "オフ", .ko: "끄기", .zhCN: "关闭", .es: "Desactivado", .de: "Aus", .fr: "Désactivé", .ptBR: "Desativado"],
